「明るい」という一言の中に、実は4つの別々の量が混ざっています。ランプがどれだけ光を出しているか（光束）、その光がどの向きにどれだけ強いか（光度）、机の上がどれだけ明るいか（照度）、そして人の目にどれだけまぶしく見えるか（輝度）です。この4つを混同したまま暗記すると、必ず問題文で足をすくわれます。単位とセットで整理するのが最短ルートです。

━━━━━━━━━━━━━━━━━━━━━━
