冬に部屋が寒いのは、暖房でつくった熱が壁や窓を通って外へ逃げるからです。逃げやすさは材料の種類と厚さで決まりますが、壁は何層にも重なっているので、そのままでは比べられません。そこで「1m²の壁を、内外の温度差1℃で、1時間にどれだけの熱が通り抜けるか」という共通の物差しをつくりました。これが熱貫流率（U値）です。値が小さいほど断熱が良い、と覚えるだけで半分は終わりです。

━━━━━━━━━━━━━━━━━━━━━━
