・露点温度：その空気を冷やしていき、相対湿度が100％になる温度★
・絶対湿度が同じまま温度だけ下げると、相対湿度は上がる★
・絶対湿度が同じまま温度を上げると、相対湿度は下がる（暖房すると乾燥する理由）

【図解】温度と飽和水蒸気圧のおおよその関係
　温度｜飽和水蒸気圧の目安［Pa］｜
