梁に荷重が載ると、どこかが最も強く曲げられ、どこかが最も強く切られようとします。その分布を長さ方向に描いたのが曲げモーメント図（M図）とせん断力図（Q図）です。この2枚が描ければ、鉄筋をどこに増やすか、断面をどこで大きくするかが決まります。試験では図の形そのものを選ばせる問題が定番なので、代表的な形を丸暗記しておくのが最も効率的です。

