四角い枠は押すと簡単に平行四辺形につぶれますが、三角形はつぶれません。この性質を利用して、細い部材を三角形に組んで大きなスパンを飛ばすのがトラスです。トラスの部材には曲げが生じず、引張か圧縮の軸力しか働きません。だから材料を無駄なく使え、体育館や工場の屋根、橋に多用されます。計算も「軸力だけ」なので、慣れれば梁より簡単です。

