コンクリートは押される力にはとても強いのに、引っ張られるとあっけなく割れます。鉄筋はその逆で、引っ張りに強い。だから引張が生じる側に鉄筋を入れて役割を分担させたのが鉄筋コンクリートです。ただし2つの材料が一体で働くには条件があります。鉄筋がコンクリートにしっかり食いついていること（付着）、鉄筋が錆びないよう十分に埋まっていること（かぶり）、そして鉄筋が抜けないよう十分に埋め込まれていること（定着）です。配筋規定はすべてこの3つを守るための数値です。

